const s="24 de maio de 2026",e=`Vers\xE3o 1.0 \u2014 ${s}`,o="simitec.suporte.oficial@gmail.com",i="SIMITEC \u2014 ECIT M\xE1rcia Guedes, Bel\xE9m-PB",a="at\xE9 24 meses ap\xF3s o encerramento da edi\xE7\xE3o, salvo obriga\xE7\xE3o legal, presta\xE7\xE3o de contas, defesa de direitos, emiss\xE3o de certificados ou solicita\xE7\xE3o v\xE1lida de exclus\xE3o",r={termos:{eyebrow:"SIMITEC",title:"Termos e Condi\xE7\xF5es de Uso e Participa\xE7\xE3o",intro:"Regras de uso do site de inscri\xE7\xF5es, credenciamento e participa\xE7\xE3o nas atividades da SIMITEC.",version:e,route:"/termos",description:"Termos de uso, participa\xE7\xE3o, credenciamento, QR Code, certificados, conduta e uso de imagem e voz da SIMITEC.",sections:[{id:"apresentacao",title:"Apresenta\xE7\xE3o e ci\xEAncia dos termos",paragraphs:["A SIMITEC \xE9 um evento educacional, cient\xEDfico, tecnol\xF3gico, cultural e institucional. Estes termos explicam as regras de uso do site, das inscri\xE7\xF5es, do credenciamento, da credencial digital e da participa\xE7\xE3o nas atividades oficiais.","Ao criar conta, realizar inscri\xE7\xE3o, acessar a credencial ou participar de uma atividade, a pessoa participante declara que leu e compreendeu estes termos. Quando houver menor de idade, a participa\xE7\xE3o poder\xE1 depender de ci\xEAncia ou autoriza\xE7\xE3o do respons\xE1vel legal, conforme a regra da atividade."]},{id:"conta-inscricao",title:"Conta e inscri\xE7\xE3o",paragraphs:["A pessoa participante deve informar dados verdadeiros, completos e atualizados. O e-mail, CPF, telefone, institui\xE7\xE3o, turma, cidade e demais informa\xE7\xF5es cadastradas poder\xE3o ser usados para organizar a entrada, confirmar a participa\xE7\xE3o, emitir credenciais e enviar orienta\xE7\xF5es relacionadas ao evento.","Informa\xE7\xF5es falsas, incompletas, duplicadas, desatualizadas ou incompat\xEDveis com a finalidade do evento poder\xE3o gerar corre\xE7\xE3o cadastral, recusa de inscri\xE7\xE3o, bloqueio tempor\xE1rio, cancelamento de vaga ou impedimento de credenciamento.","Quando houver conta de acesso, a pessoa usu\xE1ria \xE9 respons\xE1vel por manter o sigilo da senha e por usar corretamente o e-mail ou outro contato informado."]},{id:"credencial",title:"Credencial e QR Code",paragraphs:["A credencial com QR Code \xE9 pessoal, individual e intransfer\xEDvel. Ela poder\xE1 ser usada para confirmar inscri\xE7\xE3o, credenciar a pessoa na entrada, registrar presen\xE7a, organizar filas, controlar vagas, validar acesso a atividades e apoiar a emiss\xE3o de certificados.","O QR Code dever\xE1 ser apresentado pela pr\xF3pria pessoa participante no credenciamento geral e, quando necess\xE1rio, nas atividades escolhidas. A equipe poder\xE1 validar o c\xF3digo pelo leitor oficial, por busca manual ou por confer\xEAncia dos dados cadastrados.","A organiza\xE7\xE3o poder\xE1 solicitar documento de identifica\xE7\xE3o, confer\xEAncia de dados ou valida\xE7\xE3o presencial quando houver d\xFAvida sobre a inscri\xE7\xE3o, inconsist\xEAncia cadastral, tentativa de uso indevido ou necessidade de seguran\xE7a operacional.","\xC9 proibido vender, ceder, emprestar, adulterar, reutilizar, fotografar para uso de terceiros ou compartilhar credencial de outra pessoa. O uso indevido poder\xE1 gerar cancelamento da inscri\xE7\xE3o, bloqueio da credencial e impedimento de participa\xE7\xE3o.","Se houver falha t\xE9cnica, internet inst\xE1vel ou indisponibilidade moment\xE2nea do leitor, a equipe poder\xE1 registrar a presen\xE7a por confer\xEAncia manual e sincronizar os dados depois."]},{id:"vagas-programacao",title:"Vagas, atividades e programa\xE7\xE3o",paragraphs:["A inscri\xE7\xE3o em atividades com vagas limitadas depende da disponibilidade e das regras de cada atividade. A inscri\xE7\xE3o geral no evento n\xE3o garante vaga autom\xE1tica em oficinas, minicursos, competi\xE7\xF5es, apresenta\xE7\xF5es, exposi\xE7\xF5es ou atividades especiais.","Cada atividade poder\xE1 ter crit\xE9rios pr\xF3prios, como ordem de inscri\xE7\xE3o, hor\xE1rio de chegada, faixa et\xE1ria, autoriza\xE7\xE3o do respons\xE1vel, material necess\xE1rio, limite f\xEDsico do espa\xE7o ou valida\xE7\xE3o pela equipe.","A programa\xE7\xE3o, os hor\xE1rios, locais, vagas, respons\xE1veis e formatos poder\xE3o ser alterados por necessidade pedag\xF3gica, t\xE9cnica, administrativa, de seguran\xE7a, acessibilidade, disponibilidade de espa\xE7o, condi\xE7\xF5es clim\xE1ticas ou for\xE7a maior."]},{id:"regras-participacao",title:"Regras de participa\xE7\xE3o",paragraphs:["A pessoa participante deve seguir as orienta\xE7\xF5es da organiza\xE7\xE3o, dos monitores, docentes, palestrantes, respons\xE1veis de sala e equipe de seguran\xE7a. \xC1reas restritas, salas t\xE9cnicas, laborat\xF3rios ou espa\xE7os reservados s\xF3 podem ser acessados com autoriza\xE7\xE3o.","A organiza\xE7\xE3o poder\xE1 limitar a entrada em espa\xE7os lotados, reorganizar filas, remanejar participantes e adotar medidas razo\xE1veis para preservar a seguran\xE7a, a acessibilidade, o funcionamento das atividades e o ambiente escolar."]},{id:"conduta",title:"Conduta e ambiente escolar",paragraphs:["A SIMITEC \xE9 um espa\xE7o de aprendizagem, conviv\xEAncia, inclus\xE3o, diversidade, cultura de paz e respeito. Toda pessoa participante deve agir com responsabilidade, cordialidade e cuidado com o espa\xE7o escolar, a equipe, estudantes, visitantes, convidados e demais participantes.","N\xE3o ser\xE3o toleradas condutas ofensivas, discriminat\xF3rias, violentas, intimidat\xF3rias, racistas, capacitistas, LGBTf\xF3bicas, mis\xF3ginas, ass\xE9dio, bullying, vandalismo, dano ao patrim\xF4nio ou qualquer comportamento incompat\xEDvel com o car\xE1ter educativo do evento."]},{id:"cultura-cosplay",title:"Atividades culturais, cosplay e props",paragraphs:["Figurinos, acess\xF3rios, props e apresenta\xE7\xF5es devem ser seguros, respeitosos, adequados ao ambiente escolar e compat\xEDveis com a circula\xE7\xE3o de estudantes, visitantes, crian\xE7as e adolescentes.","A organiza\xE7\xE3o poder\xE1 inspecionar itens, solicitar adapta\xE7\xF5es, reter temporariamente material incompat\xEDvel, impedir apresenta\xE7\xE3o ou barrar item que represente risco, perturba\xE7\xE3o, desconforto grave ao p\xFAblico ou dano ao patrim\xF4nio."],bullets:["N\xE3o s\xE3o permitidos explosivos, chamas, fuma\xE7a, l\xEDquidos para efeito c\xEAnico, subst\xE2ncias t\xF3xicas ou materiais corrosivos.","Tamb\xE9m n\xE3o s\xE3o permitidos objetos cortantes, perfurantes, r\xE9plicas realistas de armas, armas de fogo, armas brancas, airsoft, muni\xE7\xE3o ou itens com potencial de ferir terceiros.","Apresenta\xE7\xF5es, falas, trilhas e performances devem respeitar a diversidade, a cultura de paz e a classifica\xE7\xE3o adequada ao ambiente escolar."]},{id:"certificados",title:"Certificados e confirma\xE7\xE3o de presen\xE7a",paragraphs:["A confirma\xE7\xE3o de presen\xE7a poder\xE1 ser usada para organiza\xE7\xE3o interna e emiss\xE3o de certificados, quando aplic\xE1vel. A presen\xE7a poder\xE1 ser registrada por QR Code, lista manual, valida\xE7\xE3o por monitor, confer\xEAncia em sala ou outro procedimento informado pela organiza\xE7\xE3o.","A emiss\xE3o de certificados, declara\xE7\xF5es ou comprovantes depender\xE1 de inscri\xE7\xE3o v\xE1lida, dados corretos, credenciamento regular, presen\xE7a confirmada, carga hor\xE1ria m\xEDnima quando houver e valida\xE7\xE3o pela equipe respons\xE1vel.","O certificado poder\xE1 ser enviado por e-mail, disponibilizado digitalmente ou entregue por outro meio informado pela organiza\xE7\xE3o. Em inscri\xE7\xF5es em grupo, quando estudantes n\xE3o tiverem e-mail pr\xF3prio, o certificado poder\xE1 ser enviado ao e-mail do professor ou respons\xE1vel informado.","A inscri\xE7\xE3o sem comparecimento, a sa\xEDda antecipada, o uso indevido de credencial ou a aus\xEAncia de valida\xE7\xE3o de presen\xE7a podem impedir a emiss\xE3o do certificado."]},{id:"imagem-voz-finalidade",title:"Uso de imagem e voz",paragraphs:["Durante a SIMITEC, poder\xE3o ser realizados registros fotogr\xE1ficos, v\xEDdeos, capta\xE7\xE3o de \xE1udio, entrevistas, grava\xE7\xF5es de apresenta\xE7\xF5es, registros de bastidores e outras formas de documenta\xE7\xE3o institucional do evento.","Fotos, v\xEDdeos e \xE1udios do evento poder\xE3o ser usados para fins institucionais, pedag\xF3gicos, informativos, hist\xF3ricos e de divulga\xE7\xE3o da SIMITEC, sempre com respeito \xE0 dignidade, ao contexto escolar e \xE0 imagem da pessoa participante.","Esses registros n\xE3o dever\xE3o ser usados para exposi\xE7\xE3o vexat\xF3ria, discriminat\xF3ria, descontextualizada, ofensiva ou incompat\xEDvel com a finalidade educativa do evento."]},{id:"imagem-voz-locais-limites",title:"Onde os registros podem aparecer",paragraphs:["Os registros poder\xE3o aparecer no site da SIMITEC, p\xE1ginas institucionais da escola ou da institui\xE7\xE3o promotora, redes sociais oficiais, murais, apresenta\xE7\xF5es, relat\xF3rios, materiais de divulga\xE7\xE3o, v\xEDdeos-resumo, publica\xE7\xF5es comemorativas e acervos institucionais vinculados ao evento.","A SIMITEC poder\xE1 realizar registros gerais do p\xFAblico, da circula\xE7\xE3o, dos estandes, das salas e das apresenta\xE7\xF5es para documenta\xE7\xE3o contextual e coletiva do evento.","Quando houver foco individual identific\xE1vel, como retratos, entrevistas, depoimentos, cards com nome e foto, v\xEDdeos centrados em uma pessoa ou campanhas espec\xEDficas, a organiza\xE7\xE3o dever\xE1 adotar cuidado refor\xE7ado, especialmente com crian\xE7as e adolescentes."]},{id:"imagem-voz-menores",title:"Menores de idade e respons\xE1veis",paragraphs:["No caso de crian\xE7as e adolescentes, a SIMITEC observar\xE1 o melhor interesse do menor, a dignidade, a imagem, a identidade e a integridade moral da pessoa participante.","Para usos destacados de imagem e voz, entrevistas, depoimentos ou conte\xFAdos com protagonismo individual, a organiza\xE7\xE3o poder\xE1 exigir ci\xEAncia ou autoriza\xE7\xE3o do respons\xE1vel legal, especialmente quando a pessoa participante for menor de idade.","Quando houver restri\xE7\xE3o ou n\xE3o autoriza\xE7\xE3o formal, a organiza\xE7\xE3o adotar\xE1 esfor\xE7os razo\xE1veis para evitar capta\xE7\xE3o destacada, publica\xE7\xE3o individualizada e identifica\xE7\xE3o nominal do menor em materiais futuros."]},{id:"imagem-voz-restricao-revogacao",title:"N\xE3o autoriza\xE7\xE3o e revoga\xE7\xE3o",paragraphs:["A pessoa participante, ou seu respons\xE1vel legal quando aplic\xE1vel, poder\xE1 informar que n\xE3o deseja o uso destacado de imagem e voz. Essa manifesta\xE7\xE3o dever\xE1 ser feita pelos canais oficiais ou durante o credenciamento, quando a op\xE7\xE3o estiver dispon\xEDvel.","A autoriza\xE7\xE3o eventualmente concedida poder\xE1 ser revogada para usos futuros. A revoga\xE7\xE3o n\xE3o torna irregular o uso feito de forma v\xE1lida antes do pedido.","Pode haver limita\xE7\xE3o t\xE9cnica para retirar materiais impressos, v\xEDdeos j\xE1 distribu\xEDdos, publica\xE7\xF5es j\xE1 compartilhadas, registros hist\xF3ricos, cenas coletivas ou materiais em que a remo\xE7\xE3o seja invi\xE1vel ou desproporcional."]},{id:"seguranca",title:"Seguran\xE7a e responsabilidade",paragraphs:["A pessoa participante deve cuidar de seus pertences pessoais, como celular, mochila, documentos, figurinos, materiais de apresenta\xE7\xE3o e equipamentos. A organiza\xE7\xE3o adotar\xE1 medidas razo\xE1veis de apoio e seguran\xE7a compat\xEDveis com o evento.","Em situa\xE7\xF5es de risco, emerg\xEAncia, desorganiza\xE7\xE3o, dano ao patrim\xF4nio ou descumprimento de orienta\xE7\xF5es, a equipe poder\xE1 intervir, reorganizar o fluxo, solicitar retirada de item, acionar respons\xE1veis legais ou encaminhar o caso \xE0 coordena\xE7\xE3o da institui\xE7\xE3o."]},{id:"cancelamento",title:"Cancelamento, suspens\xE3o ou impedimento",paragraphs:["A organiza\xE7\xE3o poder\xE1 advertir, retirar de atividade, cancelar inscri\xE7\xE3o, bloquear credencial ou impedir perman\xEAncia de participante que pratique fraude cadastral, use credencial de terceiro, descumpra orienta\xE7\xF5es de seguran\xE7a, cause tumulto, porte item proibido, danifique patrim\xF4nio ou viole os documentos oficiais do evento.","As medidas ser\xE3o aplicadas de forma proporcional \xE0 situa\xE7\xE3o e poder\xE3o envolver comunica\xE7\xE3o \xE0 coordena\xE7\xE3o, respons\xE1veis legais ou canais institucionais competentes."]},{id:"alteracoes-termos",title:"Altera\xE7\xF5es destes termos",paragraphs:["Estes termos poder\xE3o ser atualizados para refletir mudan\xE7as legais, operacionais, pedag\xF3gicas, t\xE9cnicas ou institucionais. A vers\xE3o publicada no site ser\xE1 a refer\xEAncia de consulta da edi\xE7\xE3o atual."]},{id:"contato-termos",title:"Contato institucional",paragraphs:[`D\xFAvidas sobre estes termos, participa\xE7\xE3o, credenciais ou regras do evento podem ser encaminhadas \xE0 organiza\xE7\xE3o da SIMITEC por meio do canal institucional: ${o}.`,"Este documento inclui as regras de uso de imagem e voz e deve ser lido em conjunto com a Pol\xEDtica de Privacidade e as orienta\xE7\xF5es espec\xEDficas de cada atividade da SIMITEC."]}],actions:[["Pol\xEDtica de Privacidade","/privacidade"],["Cr\xE9ditos","/creditos"]]},privacidade:{eyebrow:"Dados pessoais",title:"Pol\xEDtica de Privacidade",intro:"Como os dados dos participantes podem ser coletados, utilizados, protegidos e tratados no contexto da SIMITEC.",version:e,route:"/privacidade",description:"Pol\xEDtica de Privacidade da SIMITEC com resumo sobre dados tratados, finalidades, seguran\xE7a, direitos e contato institucional.",sections:[{id:"visao-geral",title:"Vis\xE3o geral",paragraphs:["Esta Pol\xEDtica de Privacidade explica, em linguagem simples, como a SIMITEC pode tratar dados pessoais para organizar inscri\xE7\xF5es, credenciamento, presen\xE7a, comunica\xE7\xE3o, seguran\xE7a, certificados e registros institucionais do evento.","Tratamento de dados significa qualquer uso de informa\xE7\xE3o relacionada a uma pessoa, como coleta, registro, consulta, organiza\xE7\xE3o, armazenamento, atualiza\xE7\xE3o, compartilhamento restrito ou elimina\xE7\xE3o.",`A organiza\xE7\xE3o institucional do evento \xE9 realizada pela ${i}. Quando atuar definindo finalidades e meios essenciais do tratamento, a institui\xE7\xE3o promotora ser\xE1 considerada controladora dos dados no contexto da SIMITEC.`]},{id:"dados-tratados",title:"Quais dados podem ser coletados",paragraphs:["A SIMITEC poder\xE1 tratar dados compat\xEDveis com a realiza\xE7\xE3o do evento, como nome completo, nome social, e-mail, telefone, CPF quando necess\xE1rio, institui\xE7\xE3o ou escola, cidade, turma, s\xE9rie, perfil de participa\xE7\xE3o, atividades escolhidas, presen\xE7a, QR Code, credencial, certificados e contatos com a organiza\xE7\xE3o.","Tamb\xE9m poder\xE3o existir dados de acessibilidade ou apoio especial quando forem necess\xE1rios para acolhimento, inclus\xE3o, seguran\xE7a ou organiza\xE7\xE3o da participa\xE7\xE3o. Esses dados devem ter acesso restrito \xE0s pessoas que realmente precisam deles.","O site n\xE3o deve solicitar documentos, informa\xE7\xF5es sens\xEDveis ou dados adicionais sem necessidade operacional, pedag\xF3gica, administrativa ou de seguran\xE7a."]},{id:"finalidades",title:"Para que os dados s\xE3o usados",paragraphs:["Os dados poder\xE3o ser usados para criar conta, realizar inscri\xE7\xE3o, confirmar participa\xE7\xE3o, organizar vagas, escolher atividades, emitir credenciais, gerar QR Code, controlar acesso, registrar presen\xE7a, administrar filas, garantir seguran\xE7a, emitir certificados e responder solicita\xE7\xF5es.","Os dados tamb\xE9m poder\xE3o ser usados para melhorar a experi\xEAncia da pessoa participante, corrigir informa\xE7\xF5es, facilitar o atendimento, evitar retrabalho no credenciamento, organizar grupos, adaptar fluxos do evento e enviar orienta\xE7\xF5es \xFAteis sobre hor\xE1rios, locais, regras ou mudan\xE7as da programa\xE7\xE3o.","Os dados poder\xE3o apoiar hist\xF3rico institucional, documenta\xE7\xE3o do evento, relat\xF3rios internos, preven\xE7\xE3o a fraude, corre\xE7\xE3o cadastral e comunica\xE7\xE3o operacional.","Os dados n\xE3o ser\xE3o usados para finalidades comerciais externas ao evento, salvo se houver informa\xE7\xE3o institucional expressa e adequada ao caso."]},{id:"resumo-dados",title:"Resumo dos dados e crit\xE9rios",table:{caption:"Resumo dos principais tipos de dados tratados, finalidades e crit\xE9rios de reten\xE7\xE3o da SIMITEC.",columns:["Tipo de dado","Finalidade","Reten\xE7\xE3o ou crit\xE9rio"],rows:[["Identifica\xE7\xE3o e contato","Inscri\xE7\xE3o, comunica\xE7\xE3o, confirma\xE7\xE3o de conta e credenciamento.",a],["Institui\xE7\xE3o, turma, cidade e perfil","Organiza\xE7\xE3o de listas, grupos, atividades, relat\xF3rios internos e certificados.",a],["Atividades escolhidas e presen\xE7a","Controle de vagas, presen\xE7a, filas, acesso \xE0s atividades e emiss\xE3o de certificados.",a],["Credencial e QR Code","Controle de acesso, organiza\xE7\xE3o, seguran\xE7a operacional e preven\xE7\xE3o de uso indevido.",a],["Acessibilidade e apoio especial","Inclus\xE3o, acolhimento, seguran\xE7a e adapta\xE7\xE3o razo\xE1vel de participa\xE7\xE3o.","Pelo menor tempo necess\xE1rio para a finalidade, com acesso restrito aos cargos autorizados."]]}},{id:"base-legal-menores",title:"Base legal e crian\xE7as e adolescentes",paragraphs:["A base legal aplic\xE1vel depende da natureza da institui\xE7\xE3o, da finalidade e do caso concreto. O tratamento poder\xE1 se apoiar, quando cab\xEDvel, em obriga\xE7\xE3o legal ou regulat\xF3ria, execu\xE7\xE3o de pol\xEDticas p\xFAblicas, procedimentos relacionados \xE0 participa\xE7\xE3o, exerc\xEDcio regular de direitos, prote\xE7\xE3o da vida, seguran\xE7a, preven\xE7\xE3o a fraude ou consentimento em situa\xE7\xF5es realmente opcionais.","Consentimento n\xE3o deve ser usado como justificativa gen\xE9rica para todo o tratamento. Inscri\xE7\xE3o, credenciamento, QR Code, presen\xE7a e certificados fazem parte do n\xFAcleo operacional do evento.","No tratamento de dados de crian\xE7as e adolescentes, prevalecer\xE1 o melhor interesse do menor. Quando a base aplic\xE1vel for consentimento para dados de crian\xE7a, ele dever\xE1 ser espec\xEDfico, em destaque e, quando aplic\xE1vel, fornecido por pelo menos um dos pais ou respons\xE1vel legal."]},{id:"compartilhamento",title:"Compartilhamento de dados",paragraphs:["O acesso aos dados deve ficar restrito aos funcion\xE1rios autorizados de maior cargo e \xE0s pessoas expressamente liberadas pela administra\xE7\xE3o quando houver necessidade real para realizar a SIMITEC.","Equipe de credenciamento, suporte, comunica\xE7\xE3o ou opera\xE7\xE3o s\xF3 deve acessar os dados compat\xEDveis com sua fun\xE7\xE3o, respeitando permiss\xF5es do sistema, controle de cargo e necessidade de uso.","Prestadores de hospedagem, e-mail, suporte, QR Code, banco de dados ou certificados poder\xE3o tratar dados apenas dentro das finalidades do evento e conforme instru\xE7\xF5es da organiza\xE7\xE3o.","A SIMITEC n\xE3o vende nem aluga dados pessoais."]},{id:"retencao",title:"Armazenamento, reten\xE7\xE3o e descarte",paragraphs:[`A SIMITEC manter\xE1 os dados pessoais pelo prazo de ${a}`,"Quando a finalidade terminar e n\xE3o houver necessidade leg\xEDtima de guarda, os dados dever\xE3o ser eliminados, anonimizados ou preservados apenas em formato compat\xEDvel com a legisla\xE7\xE3o e as regras institucionais aplic\xE1veis.","Registros estat\xEDsticos sem identifica\xE7\xE3o pessoal poder\xE3o ser mantidos por mais tempo para hist\xF3rico institucional, relat\xF3rios e melhoria das pr\xF3ximas edi\xE7\xF5es."]},{id:"seguranca-dados",title:"Seguran\xE7a da informa\xE7\xE3o",paragraphs:["A SIMITEC adota medidas t\xE9cnicas e administrativas razo\xE1veis para proteger dados pessoais contra acesso n\xE3o autorizado, perda, altera\xE7\xE3o, divulga\xE7\xE3o indevida, destrui\xE7\xE3o ou uso incompat\xEDvel com a finalidade informada.","Essas medidas podem incluir controle de acesso por perfil, senhas, autentica\xE7\xE3o no painel administrativo, revis\xE3o de permiss\xF5es, registros de a\xE7\xF5es cr\xEDticas, backups, atualiza\xE7\xE3o de sistemas, conex\xE3o segura, orienta\xE7\xE3o da equipe e guarda cuidadosa de listas f\xEDsicas.","Nenhum ambiente digital \xE9 absolutamente livre de riscos. Se ocorrer incidente com possibilidade de risco ou dano relevante, a organiza\xE7\xE3o dever\xE1 avaliar o caso e adotar medidas de conten\xE7\xE3o, corre\xE7\xE3o e comunica\xE7\xE3o conforme a legisla\xE7\xE3o aplic\xE1vel."]},{id:"direitos",title:"Direitos da pessoa titular",paragraphs:["A pessoa titular dos dados, ou seu representante legal, poder\xE1 solicitar confirma\xE7\xE3o de tratamento, acesso aos dados, corre\xE7\xE3o de informa\xE7\xF5es incompletas ou desatualizadas, anonimiza\xE7\xE3o, bloqueio, elimina\xE7\xE3o quando cab\xEDvel, informa\xE7\xE3o sobre compartilhamento, oposi\xE7\xE3o nas hip\xF3teses legais adequadas e revoga\xE7\xE3o do consentimento quando essa for a base utilizada.","Para proteger a pr\xF3pria pessoa titular, a organiza\xE7\xE3o poder\xE1 solicitar informa\xE7\xF5es m\xEDnimas para confirmar a identidade de quem faz o pedido ou de seu representante legal.",`Solicita\xE7\xF5es sobre corre\xE7\xE3o, atualiza\xE7\xE3o, exclus\xE3o de dados, revoga\xE7\xE3o de consentimento quando cab\xEDvel, d\xFAvidas ou restri\xE7\xF5es de imagem devem ser encaminhadas ao e-mail ${o}. O pedido deve informar nome completo, contato, descri\xE7\xE3o do que precisa ser corrigido ou exclu\xEDdo e, quando necess\xE1rio, comprovante de v\xEDnculo ou representa\xE7\xE3o legal.`,"A exclus\xE3o poder\xE1 n\xE3o ser imediata quando houver obriga\xE7\xE3o legal, necessidade de certificado, auditoria, seguran\xE7a, preven\xE7\xE3o de fraude, exerc\xEDcio regular de direitos ou registro institucional leg\xEDtimo."]},{id:"controlador-contato",title:"Controlador, contato e encarregado",paragraphs:[`Controlador \xE9 quem define por que e como os dados s\xE3o tratados. No contexto da SIMITEC, essa fun\xE7\xE3o cabe \xE0 institui\xE7\xE3o promotora do evento: ${i}.`,`Canal de contato para privacidade e solicita\xE7\xF5es de titulares: ${o}.`,"Enquanto n\xE3o houver encarregado de dados nomeado em p\xE1gina pr\xF3pria, as solicita\xE7\xF5es dever\xE3o ser recebidas pelo e-mail oficial da SIMITEC e encaminhadas \xE0 gest\xE3o respons\xE1vel da institui\xE7\xE3o."]},{id:"atualizacoes-politica",title:"Atualiza\xE7\xF5es desta pol\xEDtica",paragraphs:["Esta Pol\xEDtica de Privacidade poder\xE1 ser atualizada para refletir mudan\xE7as legais, t\xE9cnicas, operacionais ou institucionais. A vers\xE3o publicada nesta p\xE1gina ser\xE1 a refer\xEAncia de consulta da edi\xE7\xE3o atual."]}],actions:[["Termos e Condi\xE7\xF5es","/termos"],["Cr\xE9ditos","/creditos"]]},creditos:{eyebrow:"Cr\xE9ditos",title:"Cr\xE9ditos",intro:"Informa\xE7\xF5es sobre organiza\xE7\xE3o, desenvolvimento, identidade visual e materiais da SIMITEC.",version:e,route:"/creditos",sections:[{id:"organizacao-creditos",title:"Organiza\xE7\xE3o institucional",paragraphs:[`A SIMITEC \xE9 uma iniciativa educacional, cient\xEDfica, tecnol\xF3gica, cultural e institucional realizada pela ${i}, com participa\xE7\xE3o da comunidade escolar e de equipes de organiza\xE7\xE3o, ensino, apoio, comunica\xE7\xE3o, tecnologia e acolhimento.`,"A coordena\xE7\xE3o geral do evento \xE9 respons\xE1vel pelo planejamento, programa\xE7\xE3o, orienta\xE7\xE3o oficial, credenciamento, comunica\xE7\xE3o com participantes, organiza\xE7\xE3o das atividades e valida\xE7\xE3o das regras publicadas no site.","As informa\xE7\xF5es oficiais da SIMITEC devem ser consultadas prioritariamente quando houver diverg\xEAncia com comunica\xE7\xF5es informais ou conte\xFAdos reproduzidos por terceiros."]},{id:"desenvolvimento-sistema",title:"Desenvolvimento do site e do sistema",paragraphs:["O site da SIMITEC e seus fluxos de inscri\xE7\xE3o, credenciamento, controle de presen\xE7a, gera\xE7\xE3o de credenciais, QR Code, valida\xE7\xE3o de participa\xE7\xE3o e emiss\xE3o de certificados integram a estrutura digital de apoio \xE0 realiza\xE7\xE3o do evento.","O desenvolvimento, manuten\xE7\xE3o e suporte do sistema podem envolver equipe interna, estudantes, servidores, prestadores t\xE9cnicos ou parceiros autorizados, conforme o arranjo adotado pela institui\xE7\xE3o em cada edi\xE7\xE3o.","Cr\xE9ditos nominais espec\xEDficos poder\xE3o ser inclu\xEDdos apenas quando aprovados pela gest\xE3o respons\xE1vel da SIMITEC."]},{id:"identidade-visual",title:"Identidade visual e comunica\xE7\xE3o",paragraphs:["A identidade visual da SIMITEC, incluindo nome do evento, elementos gr\xE1ficos, composi\xE7\xF5es visuais, pe\xE7as institucionais, textos editoriais, sinaliza\xE7\xE3o, ilustra\xE7\xF5es e materiais de divulga\xE7\xE3o, pertence \xE0 iniciativa SIMITEC e \xE0 institui\xE7\xE3o promotora, resguardados direitos de terceiros.","A comunica\xE7\xE3o institucional deve observar coer\xEAncia com a proposta pedag\xF3gica, a linguagem escolar e os documentos legais publicados nesta \xE1rea do site."]},{id:"materiais-terceiros",title:"Conte\xFAdos e materiais de terceiros",paragraphs:["Apresenta\xE7\xF5es, trabalhos, exposi\xE7\xF5es, projetos, marcas, imagens, trilhas, fotografias, personagens, obras autorais e demais materiais submetidos por participantes ou convidados continuam sujeitos aos direitos de seus respectivos titulares.","Quando materiais de terceiros forem utilizados pela SIMITEC, isso dever\xE1 ocorrer com autoriza\xE7\xE3o, licen\xE7a, enquadramento legal pertinente ou indica\xE7\xE3o de responsabilidade da pessoa que submeteu o conte\xFAdo.","O envio ou apresenta\xE7\xE3o de conte\xFAdo por participante n\xE3o transfere automaticamente a titularidade integral da obra para a SIMITEC."]},{id:"tecnologias-licencas",title:"Tecnologias e licen\xE7as",paragraphs:["O site e os sistemas de apoio podem utilizar frameworks, bibliotecas, componentes de interface, servi\xE7os de hospedagem, solu\xE7\xF5es de QR Code, bancos de dados, autentica\xE7\xE3o, e-mail e outras tecnologias de terceiros, sujeitas \xE0s suas pr\xF3prias licen\xE7as e condi\xE7\xF5es de uso.","A exist\xEAncia de tecnologia de terceiros no site n\xE3o autoriza reprodu\xE7\xE3o indevida da identidade visual, dos materiais institucionais ou dos conte\xFAdos pr\xF3prios da SIMITEC."]},{id:"uso-materiais",title:"Uso dos materiais da SIMITEC",paragraphs:["\xC9 vedada a reprodu\xE7\xE3o enganosa, redistribui\xE7\xE3o indevida, adultera\xE7\xE3o de documentos, uso de identidade visual para fins fraudulentos, cria\xE7\xE3o de p\xE1ginas falsas de inscri\xE7\xE3o, reaproveitamento n\xE3o autorizado de credenciais ou publica\xE7\xE3o que simule comunica\xE7\xE3o oficial.","Cita\xE7\xF5es institucionais, refer\xEAncia acad\xEAmica ao evento, reprodu\xE7\xE3o jornal\xEDstica leg\xEDtima e compartilhamento de links oficiais devem preservar a integridade das informa\xE7\xF5es e a origem do conte\xFAdo."]},{id:"agradecimentos",title:"Agradecimentos",paragraphs:["A SIMITEC agradece estudantes, docentes, equipe t\xE9cnica, comunica\xE7\xE3o institucional, monitores, palestrantes, artistas, convidados, profissionais de apoio e institui\xE7\xF5es parceiras que contribuem para a realiza\xE7\xE3o de cada edi\xE7\xE3o.","Esta p\xE1gina poder\xE1 ser atualizada para refletir novas equipes, parcerias, cr\xE9ditos t\xE9cnicos, mudan\xE7as de identidade visual e evolu\xE7\xE3o do sistema."]}],actions:[["Termos e Condi\xE7\xF5es","/termos"],["Pol\xEDtica de Privacidade","/privacidade"]]}};export{r as legalPages};
